DROP TABLE IF EXISTS `yikai_banner_groups`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `yikai_banner_groups` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL COMMENT '分组名称',
  `slug` varchar(50) NOT NULL COMMENT '标识（= banners.position）',
  `height_pc` smallint(5) unsigned NOT NULL DEFAULT '500',
  `height_mobile` smallint(5) unsigned NOT NULL DEFAULT '250',
  `fullscreen` tinyint(1) NOT NULL DEFAULT '0' COMMENT '全屏大Banner（PC满屏高度）',
  `height_mode` varchar(20) NOT NULL DEFAULT 'fixed' COMMENT '高度模式 fixed/screen/cover-header',
  `autoplay_delay` int(10) unsigned NOT NULL DEFAULT '5000',
  `effect` varchar(10) NOT NULL DEFAULT 'fade' COMMENT '切换效果 fade/slide',
  `speed` smallint(5) unsigned NOT NULL DEFAULT '700' COMMENT '切换速度ms',
  `content_motion` varchar(20) NOT NULL DEFAULT 'none' COMMENT '文字入场效果',
  `background_motion` varchar(20) NOT NULL DEFAULT 'none' COMMENT '背景动效',
  `stagger` smallint(5) unsigned NOT NULL DEFAULT '120' COMMENT '文字层错峰ms',
  `navigation` tinyint(1) NOT NULL DEFAULT '1' COMMENT '显示前后导航',
  `pagination` tinyint(1) NOT NULL DEFAULT '1' COMMENT '显示分页指示器',
  `pause_hover` tinyint(1) NOT NULL DEFAULT '1' COMMENT '鼠标悬停暂停',
  `sort_order` int(11) NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` int(10) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='轮播图分组';
