  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL COMMENT '块名称（后台块库列表显示）',
  `data` longtext COMMENT '单个 section 的 JSON（settings+columns）',
