  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL COMMENT '角色名称',
  `name_en` varchar(50) NOT NULL DEFAULT '' COMMENT 'EN 角色名',
  `name_ja` varchar(50) NOT NULL DEFAULT '' COMMENT 'JA 角色名',
  `description` varchar(255) NOT NULL DEFAULT '' COMMENT '角色描述',
  `description_en` varchar(255) NOT NULL DEFAULT '' COMMENT 'EN 角色描述',
  `description_ja` varchar(255) NOT NULL DEFAULT '' COMMENT 'JA 角色描述',
  `permissions` text COMMENT '权限JSON',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态',
  `created_at` int(11) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='角色表';
